      SUBROUTINE RDINIT(LDATA,LECHO)CC---- INITIALIZE READ PACKAGECC     LIST OF COMMON BLOCKSC      INCLUDE 'IODATA.CIN'      INCLUDE 'IOFLAG.CIN'      INCLUDE 'RDBUFF.CIN'CC     LOCAL VARIABLESC      INTEGER         LDATA, LECHOCC-------------------------------------------------------------------      LDATA = LDATA      IECHO = LECHO      ILINE = 0      ICOL  = 81      IMARK = 1      NWARN = 0      NFAIL = 0      ENDFIL = .FALSE.      KTEXT = ' '      KLINE(81) = ';'      RETURNC-------------------------------------------------------------------      END